import{_ as t,o as i,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Activities Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Activities Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/activities-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Activities Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/activities-overview"}]]},"headers":[],"relativePath":"user-guide/activities-overview.md","filePath":"user-guide/activities-overview.md","lastUpdated":1786926673000}'),d={name:"user-guide/activities-overview.md"};function s(l,e,r,c,n,m){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="activities-module" tabindex="-1">Activities Module <a class="header-anchor" href="#activities-module" aria-label="Permalink to &quot;Activities Module&quot;">​</a></h1><p>CRM engagements module on the frozen platform. Mirrors the <a href="/user-guide/contacts-overview">Contacts</a> / <a href="/user-guide/companies-overview">Companies</a> reference architecture — loggable calls, emails, notes, follow-ups, and other interactions linked to Contacts, Companies, and/or Leads.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/activities">activities.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/activities">activities-developer.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/activities">activities-production.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/companies-overview">companies.md</a> · <a href="/user-guide/contacts-overview">contacts.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-activities">../api/tenant-v1-activities.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Types: <code>call</code>, <code>email</code>, <code>note</code>, <code>follow_up</code>, <code>other</code></li><li>Subject, optional body, optional due date, completion (<code>completed_at</code>)</li><li>Related links: at least one of Contact / Company / Lead (soft entitlement — FK rejected when that module is not installed)</li><li>Assignment with assignee scoping via <code>activities.assign</code></li><li>Notes + domain activity timeline</li><li>Table view with search, type/status filters, and <strong>My Activities</strong> toggle</li><li>KPIs via <code>GET /activities/stats</code></li><li>Completing an activity mirrors onto related Contact/Company/Lead timelines</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:activities</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong></li><li>Audit + activity logging</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>activities.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>complete</code></p><p>Staff can complete assigned activities with <code>activities.complete</code> (without full update).</p><p>Enable Activities from Marketplace (free). Catalog: slug <code>activities</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 28</code>. Only Leads and Tasks install automatically on new workspaces.</p><h2 id="related-modules-optional" tabindex="-1">Related modules (optional) <a class="header-anchor" href="#related-modules-optional" aria-label="Permalink to &quot;Related modules (optional)&quot;">​</a></h2><p>No hard <code>module_dependencies</code> row. Linking a Contact, Company, or Lead requires that module to be entitled; otherwise validation rejects the FK.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Calendar projection / Meetings types</li><li>Aggregating system <code>*_activities</code> timelines into this list</li><li>Communication template placeholders</li></ul>',14)])])}const h=t(d,[["render",s]]);export{u as __pageData,h as default};
